"use client";
import * as React from "react";
import { motion, useMotionValue, useReducedMotion, useSpring, useTransform } from "motion/react";
import { cn } from "../lib/cn";

interface DockContextValue {
  muisX: ReturnType<typeof useMotionValue<number>>;
  grootte: number;
  vergroting: number;
  afstand: number;
  vertical: boolean;
}

const DockContext = React.createContext<DockContextValue | null>(null);

export interface DockProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "onAnimationStart" | "onAnimationEnd" | "onDrag" | "onDragStart" | "onDragEnd"> {
  /** Rustige grootte van een icoon in pixels. */
  size?: number;
  /** Grootte onder de muis. */
  magnification?: number;
  /** Binnen hoeveel pixels de vergroting begint. */
  distance?: number;
  vertical?: boolean;
}

/**
 * Dock — rij iconen die opzwelt onder de muis, zoals de dock van macOS.
 * De afstand tot de muis stuurt de grootte via een spring per item.
 */
export const Dock = React.forwardRef<HTMLDivElement, DockProps>(function Dock(
  { size = 42, magnification = 68, distance = 130, vertical, className, children, ...rest },
  ref
) {
  const muisX = useMotionValue(Number.POSITIVE_INFINITY);

  return (
    <DockContext.Provider value={{ muisX, grootte: size, vergroting: magnification, afstand: distance, vertical: Boolean(vertical) }}>
      <motion.div
        ref={ref}
        className={cn("lui-dock", vertical && "lui-dock-vertical", className)}
        style={{ ["--lui-dock-size" as string]: `${size}px` }}
        onMouseMove={(event) => muisX.set(vertical ? event.clientY : event.clientX)}
        onMouseLeave={() => muisX.set(Number.POSITIVE_INFINITY)}
        {...rest}
      >
        {children}
      </motion.div>
    </DockContext.Provider>
  );
});

export interface DockItemProps
  extends Omit<React.ButtonHTMLAttributes<HTMLButtonElement>, "onAnimationStart" | "onAnimationEnd" | "onDrag" | "onDragStart" | "onDragEnd"> {
  /** Tekst die boven het icoon verschijnt bij het zweven. */
  label?: React.ReactNode;
  /** Stipje eronder, bv. voor "staat open". */
  active?: boolean;
  /** Rendert als link in plaats van als knop. */
  href?: string;
}

/** Eén icoon in de dock. */
export const DockItem = React.forwardRef<HTMLButtonElement, DockItemProps>(function DockItem(
  { label, active, href, className, children, ...rest },
  ref
) {
  const context = React.useContext(DockContext);
  if (!context) throw new Error("DockItem moet binnen <Dock> staan.");
  const rustig = useReducedMotion();

  const eigen = React.useRef<HTMLDivElement>(null);

  /* Afstand tussen het midden van dit item en de muis. */
  const verschil = useTransform(context.muisX, (muis: number) => {
    const rect = eigen.current?.getBoundingClientRect();
    if (!rect) return Number.POSITIVE_INFINITY;
    const midden = context.vertical ? rect.top + rect.height / 2 : rect.left + rect.width / 2;
    return muis - midden;
  });

  const doel = useTransform(
    verschil,
    [-context.afstand, 0, context.afstand],
    [context.grootte, context.vergroting, context.grootte],
    { clamp: true }
  );
  const maat = useSpring(doel, { stiffness: 260, damping: 22, mass: 0.2 });

  const inhoud = (
    <>
      <span className="lui-dock-icon">{children}</span>
      {label && <span className="lui-dock-label">{label}</span>}
      {active && <span className="lui-dock-dot" aria-hidden="true" />}
    </>
  );

  return (
    <motion.div
      ref={eigen}
      className="lui-dock-slot"
      style={rustig ? { width: context.grootte, height: context.grootte } : { width: maat, height: maat }}
    >
      {href ? (
        <a href={href} className={cn("lui-dock-item", className)} aria-label={typeof label === "string" ? label : undefined}>
          {inhoud}
        </a>
      ) : (
        <button
          ref={ref}
          type="button"
          className={cn("lui-dock-item", className)}
          aria-label={typeof label === "string" ? label : undefined}
          {...rest}
        >
          {inhoud}
        </button>
      )}
    </motion.div>
  );
});

/* ==================== Motion-laag (optioneel) ==================== */
/* Alleen de extra's die de motion-varianten nodig hebben. De panelen zelf
   gebruiken dezelfde klassen als Drawer en Segmented. */

/* De CSS-keyframes van Drawer uitzetten: motion regelt de beweging. */
.lui-motion-drawer { animation: none !important; }

.lui-motion-handle {
  display: grid; place-items: center; padding: 10px 0 4px;
  cursor: grab; touch-action: none; flex: none;
}
.lui-motion-handle:active { cursor: grabbing; }
.lui-motion-handle > span {
  display: block; width: 42px; height: 4px;
  border-radius: var(--r-full); background: var(--border-strong);
}
.lui-motion-handle-vertical { padding: 4px 10px 4px 4px; }
.lui-motion-handle-vertical > span { width: 4px; height: 42px; }

/* ---------- ReorderList ---------- */
.lui-reorder {
  display: flex; flex-direction: column; gap: 8px;
  list-style: none; margin: 0; padding: 0;
}
.lui-reorder-x { flex-direction: row; }

.lui-reorder-item {
  position: relative; display: flex; align-items: center; gap: 10px;
  padding: 11px 13px; background: var(--surface);
  border: 1px solid var(--border); border-radius: var(--r-md);
  cursor: grab; touch-action: none; user-select: none;
}
.lui-reorder-item:active { cursor: grabbing; }
.lui-reorder-item:has(.lui-reorder-handle) { cursor: default; }

.lui-reorder-handle {
  display: inline-grid; place-items: center; flex: none;
  color: var(--text-3); cursor: grab; touch-action: none;
}
.lui-reorder-handle:active { cursor: grabbing; }
.lui-reorder-content { flex: 1; min-width: 0; }

/* ---------- MotionSegmented ---------- */
/* De meeschuivende achtergrond vervangt de statische van Segmented. */
.lui-motion-segmented .lui-segmented-item { position: relative; }
.lui-motion-segmented .lui-segmented-item[data-state="active"] {
  background: transparent; box-shadow: none;
}
.lui-motion-segmented-indicator {
  position: absolute; inset: 0; z-index: 0;
  border-radius: var(--r-xs); background: var(--surface); box-shadow: var(--sh-xs);
}
.lui-motion-segmented .lui-segmented-item > *:not(.lui-motion-segmented-indicator) {
  position: relative; z-index: 1;
}

/* ---------- OtpVerification ---------- */
.lui-otpv {
  position: relative; width: 100%; max-width: 330px;
  padding: calc(16px * var(--density)) 24px calc(24px * var(--density));
  background: var(--surface); border: 1px solid var(--border);
  border-radius: var(--r-2xl); box-shadow: var(--sh-lg);
  overflow: hidden; text-align: center;
}
.lui-otpv-handle {
  display: block; width: 40px; height: 4px; margin: 0 auto 16px;
  border-radius: var(--r-full); background: var(--border-strong);
}

.lui-otpv-head { position: relative; height: 78px; }
.lui-otpv-head-layer { position: absolute; inset-inline: 0; top: 0; }
.lui-otpv-title { font-size: var(--fs-lg); font-weight: 650; letter-spacing: -0.01em; color: var(--text); }
.lui-otpv-title-ok { color: var(--green); }
.lui-otpv-text { margin-top: 8px; font-size: var(--fs-sm); line-height: 1.5; color: var(--text-3); }

.lui-otpv-stage { position: relative; height: 150px; }
.lui-otpv-anchor { position: absolute; left: 50%; top: 50%; width: 0; height: 0; }

.lui-otpv-links { position: absolute; left: 50%; top: 50%; overflow: visible; transform: translate(-50%, -50%); }
.lui-otpv-links path {
  fill: none; stroke-width: 1.5; stroke-linecap: round;
  stroke: color-mix(in srgb, var(--accent) 45%, transparent);
}

.lui-otpv-box {
  position: absolute; left: 0; top: 0; display: grid; place-items: center;
  border: 1px solid var(--border-strong); border-radius: var(--r-lg);
  background: var(--surface-2);
  font-size: 22px; font-weight: 550; color: var(--text);
  transition: border-color var(--dur) var(--ease), box-shadow var(--dur) var(--ease),
              background var(--dur) var(--ease);
}
.lui-otpv-box[data-active] {
  border-color: var(--accent);
  box-shadow: 0 0 22px -2px color-mix(in srgb, var(--accent) 45%, transparent);
}
.lui-otpv-box[data-state="checking"] { border-color: color-mix(in srgb, var(--accent) 70%, transparent); }
.lui-otpv-box[data-state="error"] { border-color: var(--red); background: var(--red-tint); }
.lui-otpv-caret {
  width: 2px; height: 24px; border-radius: var(--r-full); background: var(--text-2);
  animation: lui-otpv-caret 1s steps(1, end) infinite;
}
@keyframes lui-otpv-caret { 0%, 45% { opacity: 1; } 50%, 100% { opacity: 0; } }

.lui-otpv-badge {
  position: absolute; left: 0; top: 0; display: grid; place-items: center;
  border: 1px solid var(--green); border-radius: var(--r-lg);
  background: color-mix(in srgb, var(--green) 12%, transparent);
}
.lui-otpv-badge path {
  fill: none; stroke: var(--green); stroke-width: 2.4;
  stroke-linecap: round; stroke-linejoin: round;
}

.lui-otpv-burst { position: absolute; left: 0; top: 0; pointer-events: none; }
.lui-otpv-burst i { position: absolute; left: 0; top: 0; display: block; background: var(--green); }

.lui-otpv-input {
  position: absolute; inset-inline: 0; top: 50%; height: 64px;
  transform: translateY(-50%);
  border: 0; background: transparent; color: transparent; caret-color: transparent;
  opacity: 0; outline: none; cursor: text; font: inherit;
}
.lui-otpv-input:disabled { cursor: default; }

.lui-otpv-foot { position: relative; height: 22px; font-size: var(--fs-sm); }
.lui-otpv-foot > * { position: absolute; inset-inline: 0; top: 0; }
.lui-otpv-resend { color: var(--text-3); }
.lui-otpv-resend button {
  border: 0; background: none; padding: 0; font: inherit; font-weight: 650;
  color: var(--text); cursor: pointer; text-underline-offset: 3px;
}
.lui-otpv-resend button:hover:not(:disabled) { text-decoration: underline; }
.lui-otpv-resend button:focus-visible { outline: none; box-shadow: var(--ring); border-radius: var(--r-xs); }
.lui-otpv-error { color: var(--red); font-weight: 600; line-height: 1.4; }
.lui-otpv-secure {
  display: inline-flex; align-items: center; justify-content: center; gap: 6px;
  color: var(--green); font-weight: 600;
}

/* ---------- OtpVerification: variant "orbit" en de extra's ---------- */
.lui-otpv[data-variant="orbit"] .lui-otpv-stage { height: 186px; }
.lui-otpv-orbit { position: absolute; left: 0; top: 0; width: 0; height: 0; }

.lui-otpv-glow {
  position: absolute; inset: 0; pointer-events: none;
  background: radial-gradient(70% 55% at 50% 62%, color-mix(in srgb, var(--green) 16%, transparent), transparent 70%);
}

.lui-otpv-chip {
  display: grid; place-items: center; width: 38px; height: 38px; margin: 0 auto 12px;
  border: 1px solid var(--accent-border); border-radius: var(--r-full);
  background: var(--accent-tint); color: var(--accent);
  transition: border-color var(--dur) var(--ease), background var(--dur) var(--ease), color var(--dur) var(--ease);
}
.lui-otpv-chip[data-ok] {
  border-color: var(--green-border); background: var(--green-tint); color: var(--green);
}

/* Woord in de titel dat de accentkleur krijgt: <span className="lui-otpv-accent">OTP</span> */
.lui-otpv-accent { color: var(--accent); }

.lui-otpv-rings { position: absolute; left: 0; top: 0; pointer-events: none; }
.lui-otpv-rings i {
  position: absolute; left: 50%; top: 50%; display: block;
  width: 96px; height: 96px; margin: -48px 0 0 -48px;
  border: 1.5px solid var(--green); border-radius: var(--r-full);
}

.lui-otpv-timer { color: var(--text-2); font-weight: 600; font-variant-numeric: tabular-nums; }

.lui-otpv-cta {
  display: flex; align-items: center; justify-content: center; gap: 8px;
  width: 100%; height: calc(44px * var(--density)); margin-top: 16px;
  border: 1px solid transparent; border-radius: var(--r-md);
  background: var(--accent); color: var(--accent-fg);
  font: inherit; font-size: var(--fs-base); font-weight: 650; cursor: pointer;
  transition: background var(--dur-fast) var(--ease), color var(--dur-fast) var(--ease),
              border-color var(--dur-fast) var(--ease), opacity var(--dur-fast) var(--ease);
}
.lui-otpv-cta:hover:not(:disabled) { background: var(--accent-hover); }
.lui-otpv-cta:focus-visible { outline: none; box-shadow: var(--ring); }
.lui-otpv-cta:disabled { cursor: not-allowed; opacity: .55; }
.lui-otpv-cta[data-state="busy"] {
  background: var(--surface-2); color: var(--text-2); border-color: var(--border-strong); opacity: 1;
}
.lui-otpv-cta[data-state="done"] {
  background: var(--green); color: var(--text-inv); opacity: 1; cursor: default;
}
.lui-otpv-cta-spin {
  width: 15px; height: 15px; flex: none; border-radius: var(--r-full);
  border: 2px solid color-mix(in srgb, var(--text-3) 45%, transparent);
  border-top-color: var(--accent);
  animation: lui-spin .7s linear infinite;
}

/* ---------- UploadButton ---------- */
.lui-upb {
  position: relative; display: flex; align-items: center; gap: 6px;
  width: 100%; max-width: 420px; padding: 5px;
  border: 1px solid var(--border); border-radius: var(--r-full);
  background: var(--surface-2); box-shadow: var(--sh-xs);
}
.lui-upb-file { position: absolute; width: 1px; height: 1px; opacity: 0; pointer-events: none; }

.lui-upb-field {
  display: flex; align-items: center; gap: 9px; flex: 1; min-width: 0;
  height: calc(38px * var(--density)); padding: 0 14px;
  border: 0; border-radius: var(--r-full);
  background: var(--surface); color: var(--text-2);
  font: inherit; font-size: var(--fs-base); text-align: left; cursor: pointer;
  transition: color var(--dur-fast) var(--ease), background var(--dur-fast) var(--ease);
}
.lui-upb-field:hover:not(:disabled) { color: var(--text); }
.lui-upb-field:focus-visible { outline: none; box-shadow: var(--ring); }
.lui-upb-field:disabled { cursor: default; }
.lui-upb-field > svg { flex: none; color: var(--text-3); }
.lui-upb-name { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.lui-upb[data-stage="uploading"] .lui-upb-field,
.lui-upb[data-stage="done"] .lui-upb-field,
.lui-upb[data-stage="error"] .lui-upb-field { opacity: 0; }

.lui-upb-action {
  position: relative; display: inline-flex; align-items: center; justify-content: center;
  flex: none; height: calc(38px * var(--density)); padding: 0 18px;
  border: 0; border-radius: var(--r-full); overflow: hidden;
  background: var(--accent); color: var(--accent-fg);
  font: inherit; font-size: var(--fs-base); font-weight: 650; white-space: nowrap; cursor: pointer;
  transition: background var(--dur) var(--ease), color var(--dur) var(--ease);
}
.lui-upb-action:hover:not(:disabled) { background: var(--accent-hover); }
.lui-upb-action:focus-visible { outline: none; box-shadow: var(--ring); }
.lui-upb-action:disabled { cursor: default; }
.lui-upb-action[data-state="idle"]:disabled { opacity: .55; }
.lui-upb-action[data-state="uploading"] { cursor: progress; }
.lui-upb-action[data-state="done"] { background: var(--text); color: var(--surface); }
.lui-upb-action[data-state="error"] { background: var(--red); color: var(--text-inv); cursor: pointer; }

/* De voortgang vult de knop van links naar rechts. */
.lui-upb-progress {
  position: absolute; inset: 0; transform-origin: left center;
  background: color-mix(in srgb, var(--text) 22%, transparent);
}
.lui-upb-action[data-state="done"] .lui-upb-progress { opacity: 0; }
.lui-upb-label {
  position: relative; display: inline-flex; align-items: center; gap: 7px;
}

/* Zodra het uploaden begint, klapt de knop over het hele veld open. */
.lui-upb[data-stage="uploading"] .lui-upb-action,
.lui-upb[data-stage="done"] .lui-upb-action,
.lui-upb[data-stage="error"] .lui-upb-action {
  position: absolute; left: 5px; right: 5px; top: 5px; bottom: 5px;
  height: auto; padding: 0 18px;
}
.lui-upb[data-stage="uploading"],
.lui-upb[data-stage="done"],
.lui-upb[data-stage="error"] { background: var(--surface); }

/* ---------- PaymentCheckout ---------- */
.lui-pay {
  width: 100%; padding: calc(20px * var(--density)) 22px calc(22px * var(--density));
  border: 1px solid var(--border); border-radius: var(--r-xl);
  background: var(--surface); box-shadow: var(--sh-md);
  container-type: inline-size;
}
.lui-pay-grid {
  display: grid; gap: 22px; align-items: start;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1.05fr);
}
.lui-pay-grid[data-collapsed] { grid-template-columns: minmax(0, 1fr); justify-items: center; }
@container (max-width: 620px) {
  .lui-pay-grid { grid-template-columns: minmax(0, 1fr); }
}

/* ---------- de kaart ---------- */
.lui-pay-cardwrap { position: relative; isolation: isolate; perspective: 1100px; width: 100%; max-width: 320px; }
.lui-pay-card {
  position: relative; z-index: 1; width: 100%; aspect-ratio: 1.586;
  transform-style: preserve-3d; will-change: transform;
}
.lui-pay-face {
  position: absolute; inset: 0; display: flex; flex-direction: column; justify-content: space-between;
  padding: 18px 20px; border-radius: var(--r-lg);
  backface-visibility: hidden; -webkit-backface-visibility: hidden;
  background: linear-gradient(140deg,
    color-mix(in srgb, var(--accent-active) 92%, #000) 0%,
    color-mix(in srgb, var(--accent) 65%, #000) 55%,
    color-mix(in srgb, var(--accent-active) 96%, #000) 100%);
  color: var(--text-inv); box-shadow: var(--sh-lg);
}
[data-theme="dark"] .lui-pay-face { color: #fff; }
.lui-pay-back { transform: rotateY(180deg); justify-content: flex-start; padding: 0; }

.lui-pay-row { display: flex; align-items: center; gap: 10px; }
.lui-pay-row-foot { justify-content: space-between; gap: 18px; }
.lui-pay-chip {
  width: 34px; height: 25px; flex: none; border-radius: 5px;
  background: linear-gradient(140deg, var(--amber), color-mix(in srgb, var(--amber) 55%, #fff));
  box-shadow: inset 0 0 0 1px rgba(0, 0, 0, .18);
}
/* Het contactloos-teken: drie boogjes, getekend met randen. */
.lui-pay-wave {
  width: 14px; height: 14px; flex: none; border-radius: var(--r-full);
  border: 1.5px solid currentColor; border-left-color: transparent; border-bottom-color: transparent;
  transform: rotate(-45deg); opacity: .8;
}
.lui-pay-brandword {
  margin-left: auto; font-size: 12px; font-weight: 700;
  letter-spacing: .16em; text-transform: uppercase; opacity: .9;
}
.lui-pay-number {
  font-family: var(--mono); font-size: clamp(15px, 4.6cqw, 19px); letter-spacing: .06em;
  font-variant-numeric: tabular-nums;
}
.lui-pay-cardlabel {
  display: block; font-size: 9px; letter-spacing: .12em; text-transform: uppercase; opacity: .65;
}
.lui-pay-cardvalue {
  display: block; margin-top: 3px; font-size: 12.5px; font-weight: 600;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 150px;
}
.lui-pay-stripe { display: block; width: 100%; height: 42px; margin-top: 22px; background: rgba(0, 0, 0, .55); }
.lui-pay-cvcrow {
  display: flex; align-items: center; justify-content: flex-end; gap: 10px;
  margin: 18px 20px 0; padding: 8px 12px;
  background: rgba(255, 255, 255, .85); border-radius: 5px; color: #14171d;
}
.lui-pay-cvc { font-family: var(--mono); font-size: 14px; letter-spacing: .18em; }

.lui-pay-glow {
  position: absolute; inset: -26%; z-index: 0; pointer-events: none; border-radius: var(--r-2xl);
  background: radial-gradient(75% 75% at 50% 50%, color-mix(in srgb, var(--accent) 60%, transparent), transparent 72%);
  filter: blur(26px);
}
.lui-pay-glow[data-tone="ok"] {
  background: radial-gradient(75% 75% at 50% 50%, color-mix(in srgb, var(--green) 62%, transparent), transparent 72%);
}
.lui-pay-glow[data-tone="error"] {
  background: radial-gradient(75% 75% at 50% 50%, color-mix(in srgb, var(--red) 55%, transparent), transparent 72%);
}

/* ---------- formulier ---------- */
.lui-pay-form { display: grid; gap: 12px; align-content: start; }
.lui-pay-head { margin-bottom: 2px; }
.lui-pay-title { font-size: var(--fs-lg); font-weight: 650; letter-spacing: -0.01em; color: var(--text); }
.lui-pay-text { margin-top: 4px; font-size: var(--fs-sm); color: var(--text-3); line-height: 1.5; }
.lui-pay-duo { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }
.lui-pay-total {
  display: flex; align-items: baseline; justify-content: space-between;
  padding-top: 10px; margin-top: 2px; border-top: 1px solid var(--border);
  font-size: var(--fs-sm); color: var(--text-3);
}
.lui-pay-total strong { font-size: var(--fs-xl); font-weight: 700; color: var(--text); letter-spacing: -0.02em; }

/* ---------- status ---------- */
.lui-pay-status {
  display: grid; justify-items: center; gap: 4px; margin-top: 20px;
  font-size: var(--fs-sm); color: var(--text-2); text-align: center;
}
.lui-pay-status strong { font-size: var(--fs-lg); font-weight: 650; color: var(--text); }
.lui-pay-status-ok strong { color: var(--green); }
.lui-pay-status-error strong { color: var(--red); }
.lui-pay-status-error .lui-btn { margin-top: 10px; }
.lui-pay-spin {
  width: 16px; height: 16px; border-radius: var(--r-full);
  border: 2px solid color-mix(in srgb, var(--text-3) 40%, transparent);
  border-top-color: var(--accent); animation: lui-spin .7s linear infinite;
}
.lui-pay-check {
  display: grid; place-items: center; width: 40px; height: 40px; margin-bottom: 6px;
  border: 1px solid var(--green-border); border-radius: var(--r-full); background: var(--green-tint);
}
.lui-pay-check path { fill: none; stroke: var(--green); stroke-width: 2.4; stroke-linecap: round; stroke-linejoin: round; }

/* ==================== Actieknoppen ==================== */
/* Gedeelde basis: zelfde maten en tokens als Button, maar met eigen binnenwerk. */
.lui-sendb, .lui-orderb, .lui-cartb, .lui-shareb-trigger, .lui-delb {
  position: relative; display: inline-flex; align-items: center; justify-content: center; gap: 8px;
  height: calc(40px * var(--density)); padding: 0 18px; border: 1px solid transparent;
  border-radius: var(--r-full); font: inherit; font-size: var(--fs-base); font-weight: 650;
  white-space: nowrap; cursor: pointer; overflow: hidden;
  transition: background var(--dur-fast) var(--ease), color var(--dur-fast) var(--ease),
              border-color var(--dur-fast) var(--ease);
}
.lui-sendb:focus-visible, .lui-orderb:focus-visible, .lui-cartb:focus-visible,
.lui-shareb-trigger:focus-visible, .lui-delb:focus-visible { outline: none; box-shadow: var(--ring); }
.lui-sendb:disabled, .lui-orderb:disabled, .lui-cartb:disabled, .lui-delb:disabled { cursor: default; }

/* ---------- SendButton ---------- */
.lui-sendb-wrap { position: relative; display: inline-flex; }
.lui-sendb { background: var(--accent); color: var(--accent-fg); }
.lui-sendb:hover:not(:disabled) { background: var(--accent-hover); }
.lui-sendb[data-state="done"] { background: var(--surface-3); color: var(--text-2); }
.lui-sendb[data-state="error"] { background: var(--red-tint); color: var(--red); border-color: var(--red-border); }
.lui-sendb-label { display: inline-flex; align-items: center; gap: 7px; }
.lui-sendb-plane {
  position: absolute; left: 50%; top: 50%; margin: -11px 0 0 -11px;
  color: var(--accent); pointer-events: none;
}

/* ---------- OrderButton ---------- */
.lui-orderb { background: var(--accent); color: var(--accent-fg); min-width: 170px; }
.lui-orderb:hover:not(:disabled) { background: var(--accent-hover); }
.lui-orderb-block { width: 100%; }
.lui-orderb[data-state="busy"] { background: var(--accent); }
.lui-orderb[data-state="done"] { background: var(--green-tint); color: var(--green); border-color: var(--green-border); }
.lui-orderb[data-state="error"] { background: var(--red-tint); color: var(--red); border-color: var(--red-border); }
.lui-orderb-label { display: inline-flex; align-items: center; gap: 8px; }
.lui-orderb-truck {
  position: absolute; left: 50%; top: 50%; margin-top: -11px; margin-left: -11px;
  display: inline-flex; align-items: center; color: var(--accent-fg); pointer-events: none;
}
.lui-orderb-dust {
  position: absolute; right: 100%; top: 60%; width: 26px; height: 2px; margin-right: 4px;
  border-radius: var(--r-full);
  background: linear-gradient(90deg, transparent, color-mix(in srgb, var(--accent-fg) 55%, transparent));
}

/* ---------- AddToCartButton ---------- */
.lui-cartb-wrap { display: inline-grid; justify-items: center; gap: 8px; }
.lui-cartb-wrap-block { width: 100%; }
.lui-cartb {
  background: var(--text); color: var(--surface);
  letter-spacing: .06em; text-transform: uppercase; font-size: 13px;
}
.lui-cartb:hover:not(:disabled) { background: color-mix(in srgb, var(--text) 88%, var(--accent)); }
.lui-cartb-block { width: 100%; }
.lui-cartb[data-state="busy"] { padding: 0; width: calc(56px * var(--density)); }
.lui-cartb-icon { display: inline-flex; }
.lui-cartb-label { display: inline-flex; }
.lui-cartb-item {
  position: absolute; left: 50%; top: 0; width: 13px; height: 13px; margin-left: -6px;
  border-radius: 3px; background: var(--amber); pointer-events: none;
}
.lui-cartb-hint { font-size: var(--fs-sm); color: var(--text-3); display: inline-flex; gap: 5px; }
.lui-cartb-hint strong { color: var(--text); font-variant-numeric: tabular-nums; }

/* ---------- ShareButton ---------- */
.lui-shareb { position: relative; display: inline-grid; place-items: center; min-height: calc(40px * var(--density)); }
.lui-shareb[data-open] { min-height: 190px; min-width: 240px; }
.lui-shareb-trigger {
  background: var(--surface); color: var(--text);
  border-color: var(--border-strong); box-shadow: var(--sh-xs);
  letter-spacing: .08em; text-transform: uppercase; font-size: 12.5px;
}
.lui-shareb-trigger:hover:not(:disabled) { background: var(--surface-hover); }
.lui-shareb-fan { position: relative; display: grid; place-items: center; width: 100%; height: 100%; }
.lui-shareb-channel {
  position: absolute; display: grid; place-items: center;
  width: 44px; height: 44px; border-radius: var(--r-full);
  border: 1px solid var(--border); background: var(--surface); color: var(--text);
  cursor: pointer; box-shadow: var(--sh-sm);
  transition: transform var(--dur-fast) var(--ease), box-shadow var(--dur-fast) var(--ease);
}
.lui-shareb-channel:hover { box-shadow: var(--sh-md); }
.lui-shareb-channel:focus-visible { outline: none; box-shadow: var(--ring); }
.lui-shareb-close {
  position: relative; display: grid; place-items: center;
  width: 44px; height: 44px; border-radius: var(--r-full);
  border: 1px solid var(--border); background: var(--surface-3); color: var(--text-2); cursor: pointer;
}
.lui-shareb-close:focus-visible { outline: none; box-shadow: var(--ring); }
.lui-shareb-hint {
  position: absolute; top: calc(50% + 34px); left: 0; right: 0; text-align: center;
  font-size: var(--fs-sm); color: var(--text-3);
}

/* ---------- DeleteButton ---------- */
.lui-delb-solid { background: var(--red); color: var(--text-inv); }
.lui-delb-solid:hover:not(:disabled) { filter: brightness(.94); }
.lui-delb-soft { background: var(--red-tint); color: var(--red); border-color: var(--red-border); }
.lui-delb-soft:hover:not(:disabled) { background: color-mix(in srgb, var(--red) 14%, transparent); }
.lui-delb[data-state="done"] { background: var(--surface-3); color: var(--text-2); border-color: var(--border); }
.lui-delb[data-state="busy"] { padding: 0; width: calc(46px * var(--density)); }
.lui-delb-bin { position: relative; display: inline-flex; z-index: 1; }
.lui-delb-lid {
  position: absolute; left: 50%; top: -1px; width: 15px; height: 2px; margin-left: -7px;
  border-radius: var(--r-full); background: currentColor; transform-origin: left center;
}
.lui-delb-label { display: inline-block; transform-origin: left center; }
/* Het dekseltje hoort niet bij het vinkje of het uitroepteken. */
.lui-delb[data-state="done"] .lui-delb-lid,
.lui-delb[data-state="error"] .lui-delb-lid { opacity: 0; }

/* ---------- NumberFlow ---------- */
.lui-numberflow {
  display: inline-flex; align-items: baseline; gap: 2px;
  font-variant-numeric: tabular-nums; font-weight: 650; color: var(--text);
  transition: color var(--dur) var(--ease);
}
.lui-numberflow-sm { font-size: var(--fs-sm); }
.lui-numberflow-md { font-size: var(--fs-lg); }
.lui-numberflow-lg { font-size: 26px; letter-spacing: -0.02em; }
.lui-numberflow-xl { font-size: 40px; letter-spacing: -0.03em; }
.lui-numberflow-up { color: var(--green); }
.lui-numberflow-down { color: var(--red); }

.lui-numberflow-digits { display: inline-flex; align-items: baseline; }
.lui-numberflow-slot {
  position: relative; display: inline-flex; justify-content: center;
  overflow: hidden; height: 1.2em; line-height: 1.2em;
}
.lui-numberflow-digit { display: block; }
.lui-numberflow-sep { display: inline-block; }

/* ---------- Dock ---------- */
.lui-dock {
  --lui-dock-size: 42px;
  display: flex; align-items: flex-end; gap: 8px;
  padding: 8px 10px; border: 1px solid var(--border); border-radius: var(--r-lg);
  background: var(--surface-2); box-shadow: var(--sh-md);
  width: max-content;
}
.lui-dock-vertical { flex-direction: column; align-items: flex-start; }

.lui-dock-slot { display: grid; place-items: center; flex: none; }
.lui-dock-item {
  position: relative; display: grid; place-items: center;
  width: 100%; height: 100%; padding: 0;
  border: 1px solid var(--border); border-radius: var(--r-md);
  background: var(--surface); color: var(--text-2); cursor: pointer;
  text-decoration: none; transition: color var(--dur-fast), border-color var(--dur-fast);
}
.lui-dock-item:hover { color: var(--accent); border-color: var(--accent); }
.lui-dock-item:focus-visible { outline: none; box-shadow: var(--ring); }
.lui-dock-icon { display: grid; place-items: center; width: 52%; height: 52%; }
.lui-dock-icon > svg { width: 100%; height: 100%; }

.lui-dock-label {
  position: absolute; bottom: calc(100% + 8px); left: 50%; transform: translateX(-50%);
  padding: 3px 8px; white-space: nowrap; pointer-events: none; opacity: 0;
  border: 1px solid var(--border); border-radius: var(--r-xs);
  background: var(--surface); box-shadow: var(--sh-md);
  font-size: 12px; color: var(--text);
  transition: opacity var(--dur-fast);
}
.lui-dock-item:hover .lui-dock-label,
.lui-dock-item:focus-visible .lui-dock-label { opacity: 1; }
.lui-dock-vertical .lui-dock-label { bottom: auto; left: calc(100% + 8px); top: 50%; transform: translateY(-50%); }

.lui-dock-dot {
  position: absolute; bottom: -5px; left: 50%; transform: translateX(-50%);
  width: 4px; height: 4px; border-radius: 50%; background: var(--accent);
}
.lui-dock-vertical .lui-dock-dot { bottom: auto; left: -5px; top: 50%; transform: translateY(-50%); }

/* ---------- AnimatedList ---------- */
.lui-animlist { display: flex; flex-direction: column; gap: 8px; margin: 0; padding: 0; list-style: none; }
.lui-animlist-item { list-style: none; }
.lui-animlist-row {
  display: flex; align-items: center; gap: 10px;
  padding: 10px 12px; border: 1px solid var(--border); border-radius: var(--r-sm);
  background: var(--surface); box-shadow: var(--sh-sm);
}

/* ---------- MultiStepLoader ---------- */
.lui-loader-overlay {
  position: fixed; inset: 0; z-index: var(--z-overlay);
  display: grid; place-items: center;
  background: color-mix(in oklab, var(--surface) 82%, transparent);
  backdrop-filter: blur(6px);
}
.lui-loader {
  display: grid; gap: 12px; padding: 18px 22px;
  border: 1px solid var(--border); border-radius: var(--r-md);
  background: var(--surface); box-shadow: var(--sh-lg);
  min-width: 260px;
}
.lui-loader-title { margin: 0; font-size: var(--fs-md); font-weight: 650; color: var(--text); }
.lui-loader-steps { display: grid; gap: 9px; margin: 0; padding: 0; list-style: none; }
.lui-loader-step { display: flex; align-items: center; gap: 10px; font-size: var(--fs-sm); color: var(--text-2); }
.lui-loader-step[data-state="busy"] { color: var(--text); font-weight: 600; }
.lui-loader-step[data-state="done"] { color: var(--text-3); }

.lui-loader-mark { display: grid; place-items: center; width: 18px; height: 18px; flex: none; color: var(--accent); }
.lui-loader-dot { width: 6px; height: 6px; border-radius: 50%; background: var(--border-strong); }
.lui-loader-spin {
  width: 14px; height: 14px; border-radius: 50%;
  border: 2px solid color-mix(in oklab, var(--accent) 28%, transparent);
  border-top-color: var(--accent);
  animation: lui-loader-spin .7s linear infinite;
}
@keyframes lui-loader-spin { to { transform: rotate(360deg); } }

/* ---------- SwipeToDelete ---------- */
.lui-swipe {
  position: relative; overflow: hidden; border-radius: var(--r-sm);
}
.lui-swipe-behind {
  position: absolute; inset: 0; display: flex; align-items: center;
  padding: 0 16px; background: var(--red); color: #fff;
  font-size: var(--fs-sm); font-weight: 600;
}
.lui-swipe-behind[data-side="left"] { justify-content: flex-end; }
.lui-swipe-behind[data-side="right"] { justify-content: flex-start; }
.lui-swipe-hint, .lui-swipe-confirm { display: inline-flex; align-items: center; gap: 7px; }
.lui-swipe-confirm {
  padding: 6px 12px; border: 0; border-radius: var(--r-xs);
  background: rgba(255, 255, 255, .18); color: #fff;
  font: inherit; font-weight: 600; cursor: pointer;
}
.lui-swipe-confirm:hover { background: rgba(255, 255, 255, .3); }
.lui-swipe-confirm:focus-visible { outline: 2px solid #fff; outline-offset: 2px; }
.lui-swipe-front { position: relative; background: var(--surface); touch-action: pan-y; cursor: grab; }
.lui-swipe-front:active { cursor: grabbing; }

/* ---------- HoldToConfirm ---------- */
.lui-hold {
  position: relative; display: inline-flex; align-items: center; justify-content: center;
  overflow: hidden; border: 1px solid var(--border-strong); border-radius: var(--r-sm);
  background: var(--surface); color: var(--text);
  font: inherit; font-weight: 600; cursor: pointer; user-select: none;
  transition: border-color var(--dur-fast), color var(--dur-fast);
}
.lui-hold-sm { height: calc(32px * var(--density)); padding: 0 12px; font-size: var(--fs-sm); }
.lui-hold-md { height: calc(38px * var(--density)); padding: 0 16px; font-size: var(--fs-sm); }
.lui-hold-lg { height: calc(44px * var(--density)); padding: 0 20px; font-size: var(--fs-base); }
.lui-hold[data-tone="red"] { border-color: color-mix(in oklab, var(--red) 45%, var(--border)); color: var(--red); }
.lui-hold[data-tone="accent"] { border-color: color-mix(in oklab, var(--accent) 45%, var(--border)); color: var(--accent); }
.lui-hold:focus-visible { outline: none; box-shadow: var(--ring); }
.lui-hold:disabled { opacity: .5; cursor: not-allowed; }

.lui-hold-fill {
  position: absolute; inset: 0; transform-origin: left center;
  background: color-mix(in oklab, var(--red) 16%, transparent);
}
.lui-hold[data-tone="accent"] .lui-hold-fill { background: color-mix(in oklab, var(--accent) 16%, transparent); }
.lui-hold[data-state="done"] { color: var(--green); border-color: color-mix(in oklab, var(--green) 45%, var(--border)); }
.lui-hold[data-state="done"] .lui-hold-fill { background: color-mix(in oklab, var(--green) 16%, transparent); }

.lui-hold-label { position: relative; display: inline-flex; align-items: center; gap: 7px; }

@media (prefers-reduced-motion: reduce) {
  .lui-loader-spin { animation-duration: 1.6s; }
}

/* ---------- DownloadButton ---------- */
.lui-dlbtn {
  position: relative; display: inline-flex; align-items: center; justify-content: center;
  overflow: hidden; border: 1px solid transparent; border-radius: var(--r-sm);
  background: var(--accent); color: var(--accent-fg);
  font: inherit; font-weight: 600; cursor: pointer;
  transition: background var(--dur) var(--ease);
}
.lui-dlbtn[data-tone="violet"] { background: var(--violet); color: #fff; }
.lui-dlbtn[data-tone="green"] { background: var(--green); color: #fff; }
.lui-dlbtn-sm { height: calc(32px * var(--density)); padding: 0 12px; font-size: var(--fs-sm); }
.lui-dlbtn-md { height: calc(38px * var(--density)); padding: 0 16px; font-size: var(--fs-sm); }
.lui-dlbtn-lg { height: calc(44px * var(--density)); padding: 0 20px; font-size: var(--fs-base); }
.lui-dlbtn:disabled { opacity: .5; cursor: not-allowed; }
.lui-dlbtn:focus-visible { outline: none; box-shadow: var(--ring); }
.lui-dlbtn[data-state="done"] { background: var(--green); color: #fff; }
.lui-dlbtn[data-state="error"] { background: var(--red); color: #fff; }

.lui-dlbtn-fill {
  position: absolute; inset: 0; transform-origin: left center;
  background: rgba(255, 255, 255, .26);
}
.lui-dlbtn-label { position: relative; display: inline-flex; align-items: center; gap: 8px; }
.lui-dlbtn-percent { font-variant-numeric: tabular-nums; opacity: .85; }

/* ringvariant */
.lui-dlbtn-ringwrap { display: inline-grid; justify-items: center; gap: 6px; }
.lui-dlbtn-ring {
  position: relative; display: grid; place-items: center;
  width: 56px; height: 56px; padding: 0;
  border: 0; border-radius: 50%; background: var(--accent); color: var(--accent-fg); cursor: pointer;
  transition: background var(--dur) var(--ease), transform var(--dur-fast);
}
.lui-dlbtn-ringwrap[data-tone="violet"] .lui-dlbtn-ring { background: var(--violet); color: #fff; }
.lui-dlbtn-ringwrap[data-tone="green"] .lui-dlbtn-ring { background: var(--green); color: #fff; }
.lui-dlbtn-ringwrap.lui-dlbtn-sm .lui-dlbtn-ring { width: 44px; height: 44px; }
.lui-dlbtn-ringwrap.lui-dlbtn-lg .lui-dlbtn-ring { width: 68px; height: 68px; }
.lui-dlbtn-ring:hover:not(:disabled) { transform: scale(1.04); }
.lui-dlbtn-ring:focus-visible { outline: none; box-shadow: var(--ring); }
.lui-dlbtn-ring:disabled { opacity: .5; cursor: not-allowed; }
.lui-dlbtn-ring[data-state="done"] { background: var(--green); color: #fff; }
.lui-dlbtn-ring[data-state="error"] { background: var(--red); color: #fff; }

.lui-dlbtn-ringsvg { position: absolute; inset: -5px; width: calc(100% + 10px); height: calc(100% + 10px); transform: rotate(-90deg); }
.lui-dlbtn-ringtrack { fill: none; stroke: var(--surface-3); stroke-width: 4; }
.lui-dlbtn-ringfill {
  fill: none; stroke: currentColor; stroke-width: 4; stroke-linecap: round;
  color: var(--accent); transition: stroke-dashoffset var(--dur) linear;
}
.lui-dlbtn-ringwrap[data-tone="violet"] .lui-dlbtn-ringfill { color: var(--violet); }
.lui-dlbtn-ringicon { display: grid; place-items: center; }
.lui-dlbtn-ringpercent { font-size: 12px; font-weight: 650; color: var(--text-2); font-variant-numeric: tabular-nums; }

/* ---------- MorphButton ---------- */
.lui-morphbtn {
  display: inline-flex; align-items: center; justify-content: center; gap: 8px;
  border: 0; border-radius: var(--r-sm);
  background: var(--accent); color: var(--accent-fg);
  font: inherit; font-weight: 650; cursor: pointer; overflow: hidden;
  transition: background var(--dur) var(--ease);
}
.lui-morphbtn-sm { height: 34px; min-width: 34px; padding: 0 16px; font-size: var(--fs-sm); }
.lui-morphbtn-md { height: 42px; min-width: 42px; padding: 0 22px; font-size: var(--fs-sm); }
.lui-morphbtn-lg { height: 50px; min-width: 50px; padding: 0 28px; font-size: var(--fs-base); }
.lui-morphbtn[data-round] { padding: 0; border-radius: 999px; }
.lui-morphbtn[data-tone="green"] { background: var(--green); color: #fff; }
.lui-morphbtn[data-tone="red"] { background: var(--red); color: #fff; }
.lui-morphbtn[data-tone="violet"] { background: var(--violet); color: #fff; }
.lui-morphbtn:disabled { cursor: default; }
.lui-morphbtn:focus-visible { outline: none; box-shadow: var(--ring); }
.lui-morphbtn-label { display: inline-flex; align-items: center; gap: 7px; white-space: nowrap; }

.lui-morphbtn-spinner {
  width: 20px; height: 20px; border-radius: 50%;
  border: 2.5px solid rgba(255, 255, 255, .35);
  border-top-color: currentColor;
  animation: lui-morphbtn-spin .7s linear infinite;
}
@keyframes lui-morphbtn-spin { to { transform: rotate(360deg); } }

/* ---------- NotificationStack ---------- */
.lui-notistack {
  --lui-ns-card: var(--surface);
  --lui-ns-border: var(--border);
  --lui-ns-title: var(--text);
  --lui-ns-sub: var(--text-3);
  --lui-ns-shadow: var(--sh-md);
  position: relative; width: 100%; max-width: 380px;
}
.lui-notistack[data-variant="glass"] {
  --lui-ns-card: rgb(255 255 255 / .1);
  --lui-ns-border: rgb(255 255 255 / .14);
  --lui-ns-title: #fff;
  --lui-ns-sub: rgb(255 255 255 / .62);
  --lui-ns-shadow: 0 10px 30px -12px rgb(0 0 0 / .55);
}
.lui-notistack-deck { position: relative; display: grid; }
.lui-notistack-expanded .lui-notistack-deck { display: flex; flex-direction: column; gap: 8px; }
.lui-notistack-item { grid-area: 1 / 1; transform-origin: top center; }
.lui-notistack-row { position: relative; }

.lui-notistack-card {
  position: relative;
  display: flex; align-items: flex-start; gap: 10px;
  padding: 12px 14px; border: 1px solid var(--lui-ns-border); border-radius: var(--r-md);
  background: var(--lui-ns-card); box-shadow: var(--lui-ns-shadow);
  cursor: grab; user-select: none; touch-action: pan-y;
}
.lui-notistack[data-variant="glass"] .lui-notistack-card {
  backdrop-filter: blur(16px) saturate(1.3); -webkit-backdrop-filter: blur(16px) saturate(1.3);
}
.lui-notistack-card:active { cursor: grabbing; }
.lui-notistack-card:focus-visible { outline: none; box-shadow: var(--ring); }
.lui-notistack-card[data-top] { box-shadow: var(--sh-lg); }
.lui-notistack[data-variant="glass"] .lui-notistack-card[data-top] { box-shadow: 0 14px 34px -12px rgb(0 0 0 / .6); }

/* Wissen-knop achter de rij: verschijnt terwijl je de rij naar links trekt. */
.lui-notistack-clear {
  position: absolute; top: 50%; inset-inline-end: 0; translate: 0 -50%;
  height: 34px; padding: 0 13px; border: 1px solid var(--lui-ns-border); border-radius: var(--r-full);
  background: var(--lui-ns-card); color: var(--lui-ns-title);
  font: inherit; font-size: 12px; font-weight: 650; cursor: pointer;
  box-shadow: var(--lui-ns-shadow);
}
.lui-notistack[data-variant="glass"] .lui-notistack-clear { backdrop-filter: blur(16px); -webkit-backdrop-filter: blur(16px); }
.lui-notistack-clear:hover { filter: brightness(1.08); }
.lui-notistack-clear:focus-visible { outline: none; box-shadow: var(--ring); }

.lui-notistack-icon {
  display: grid; place-items: center; flex: none; width: 28px; height: 28px;
  border-radius: 50%; background: var(--surface-3); color: var(--text-2);
}
.lui-notistack[data-variant="glass"] .lui-notistack-icon { border-radius: 8px; background: rgb(255 255 255 / .92); }
.lui-notistack-card[data-tone="accent"] .lui-notistack-icon { background: color-mix(in oklab, var(--accent) 15%, transparent); color: var(--accent); }
.lui-notistack-card[data-tone="green"] .lui-notistack-icon { background: color-mix(in oklab, var(--green) 15%, transparent); color: var(--green); }
.lui-notistack-card[data-tone="amber"] .lui-notistack-icon { background: color-mix(in oklab, var(--amber) 17%, transparent); color: var(--amber); }
.lui-notistack-card[data-tone="red"] .lui-notistack-icon { background: color-mix(in oklab, var(--red) 15%, transparent); color: var(--red); }
.lui-notistack-card[data-tone="blue"] .lui-notistack-icon { background: color-mix(in oklab, var(--blue) 15%, transparent); color: var(--blue); }
.lui-notistack-card[data-tone="violet"] .lui-notistack-icon { background: color-mix(in oklab, var(--violet) 15%, transparent); color: var(--violet); }
.lui-notistack[data-variant="glass"] .lui-notistack-card[data-tone] .lui-notistack-icon {
  background: color-mix(in oklab, var(--lui-ns-tone, #fff) 88%, #fff);
}

.lui-notistack-body { display: grid; gap: 2px; flex: 1; min-width: 0; }
.lui-notistack-title { font-size: var(--fs-sm); font-weight: 600; color: var(--lui-ns-title); }
.lui-notistack-desc { font-size: 12.5px; color: var(--lui-ns-sub); }
.lui-notistack-time { flex: none; font-size: 11.5px; color: var(--lui-ns-sub); }

/* Sluitknop hangt linksboven en verschijnt bij hover of focus, zoals op macOS. */
.lui-notistack-x {
  position: absolute; top: -8px; left: -8px; z-index: 2;
  display: grid; place-items: center; width: 20px; height: 20px; padding: 0;
  border: 1px solid var(--lui-ns-border); border-radius: 50%;
  background: var(--surface); color: var(--text-2); cursor: pointer;
  box-shadow: var(--sh-sm); opacity: 0; scale: .7;
  transition: opacity var(--dur-fast), scale var(--dur) var(--ease-pop);
}
.lui-notistack-card:hover .lui-notistack-x, .lui-notistack-x:focus-visible { opacity: 1; scale: 1; }
/* Kaarten achter de bovenste zijn alleen randjes: hun inhoud vervaagt. */
.lui-notistack-card > :not(.lui-notistack-x) { transition: opacity .2s var(--ease); }
.lui-notistack-item[data-behind] .lui-notistack-card > * { opacity: 0; }
.lui-notistack[data-variant="glass"] .lui-notistack-item[data-behind] .lui-notistack-card { background: rgb(255 255 255 / .07); }
.lui-notistack-title, .lui-notistack-desc { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.lui-notistack-x:hover { color: var(--text); }
.lui-notistack-x:focus-visible { outline: none; box-shadow: var(--ring); }

.lui-notistack-count {
  position: absolute; top: -9px; inset-inline-end: -6px; z-index: 10;
  min-width: 26px; padding: 2px 8px; border-radius: var(--r-full);
  background: var(--accent); color: var(--accent-fg);
  font-size: 11.5px; font-weight: 700; text-align: center;
  box-shadow: var(--sh-sm);
}

.lui-notistack-foot { display: grid; justify-items: center; gap: 10px; margin-top: 34px; }
.lui-notistack-summary { font-size: 12px; color: var(--lui-ns-sub); }
.lui-notistack-dots { display: flex; justify-content: center; gap: 5px; }
.lui-notistack-dot { width: 5px; height: 5px; border-radius: 50%; background: var(--border-strong); transition: width var(--dur) var(--ease-pop); }
.lui-notistack-dot[data-active] { width: 16px; border-radius: var(--r-full); background: var(--accent); }
.lui-notistack[data-variant="glass"] .lui-notistack-dot { background: rgb(255 255 255 / .3); }
.lui-notistack[data-variant="glass"] .lui-notistack-dot[data-active] { background: #fff; }

.lui-notistack-empty {
  margin: 0; padding: 26px; text-align: center;
  border: 1px dashed var(--border-strong); border-radius: var(--r-md);
  font-size: var(--fs-sm); color: var(--lui-ns-sub);
}
.lui-notistack[data-variant="glass"] .lui-notistack-empty { border-color: rgb(255 255 255 / .25); }

@media (prefers-reduced-motion: reduce) {
  .lui-morphbtn-spinner { animation-duration: 1.6s; }
  .lui-dlbtn-ring:hover:not(:disabled) { transform: none; }
}

/* ---------- PublishButton ---------- */
.lui-publish {
  display: inline-flex; align-items: center; gap: 10px;
  height: calc(40px * var(--density)); padding: 0 18px 0 12px;
  border: 1px solid transparent; border-radius: var(--r-sm);
  font: inherit; font-size: var(--fs-sm); font-weight: 600; cursor: pointer;
  transition: transform var(--dur-fast), box-shadow var(--dur-fast), background var(--dur);
}
.lui-publish-dark { background: var(--text); color: var(--surface); box-shadow: var(--sh-md); }
.lui-publish-light { background: var(--surface); color: var(--text); border-color: var(--border-strong); box-shadow: var(--sh-sm); }
.lui-publish-sm { height: calc(34px * var(--density)); font-size: 13px; }
.lui-publish-lg { height: calc(46px * var(--density)); font-size: var(--fs-base); }
.lui-publish:hover:not(:disabled) { transform: translateY(-1px); }
.lui-publish:focus-visible { outline: none; box-shadow: var(--ring); }
.lui-publish:disabled { cursor: default; }

.lui-publish-icon { position: relative; display: grid; place-items: center; width: 22px; height: 22px; }
.lui-publish-cloud { position: relative; display: grid; place-items: center; width: 22px; height: 22px; }
.lui-publish-cloud > svg { transition: opacity .25s var(--ease), transform .3s var(--ease-pop); }
.lui-publish-arrow {
  position: absolute; left: 50%; top: 55%; display: grid; z-index: 1;
  transform: translate(-50%, -50%);
  transition: top .3s var(--ease-pop);
}
/* Wolkjes die langs de pijl naar beneden schuiven zodra het publiceren loopt. */
.lui-publish-sky { position: absolute; inset: -6px -4px; overflow: hidden; pointer-events: none; }
.lui-publish-sky svg {
  position: absolute; left: 50%; top: 50%; opacity: 0; color: currentColor;
  translate: -50% -50%;
}
.lui-publish[data-state="busy"] .lui-publish-cloud > svg { opacity: 0; transform: scale(.6); }
.lui-publish[data-state="busy"] .lui-publish-arrow { top: 50%; animation: lui-publish-bob .9s var(--ease) infinite alternate; }
.lui-publish[data-state="busy"] .lui-publish-sky svg { animation: lui-publish-sky 1.1s linear infinite; }
.lui-publish[data-state="busy"] .lui-publish-sky svg:nth-child(2) { animation-delay: -.55s; left: 36%; }
@keyframes lui-publish-sky {
  0% { transform: translateY(-150%); opacity: 0; }
  20%, 70% { opacity: .5; }
  100% { transform: translateY(150%); opacity: 0; }
}
@keyframes lui-publish-bob { from { translate: 0 1px; } to { translate: 0 -1.5px; } }
.lui-publish-badge {
  display: grid; place-items: center; width: 18px; height: 18px; border-radius: 50%;
  background: color-mix(in oklab, currentColor 28%, transparent);
}
.lui-publish[data-state="error"] .lui-publish-badge { background: var(--red); color: #fff; }

.lui-publish-roll {
  position: relative; display: grid; overflow: hidden; height: 1.3em; line-height: 1.3em;
  transition: width .38s var(--ease-pop);
}
.lui-publish-label { grid-area: 1 / 1; white-space: nowrap; }
.lui-publish-measure { position: absolute; visibility: hidden; white-space: nowrap; pointer-events: none; }

/* ---------- LiquidUploadButton ---------- */
.lui-liquid {
  --lui-liquid-h: calc(44px * var(--density));
  --lui-liquid-main: var(--accent);
  --lui-liquid-main-fg: var(--accent-fg);
  --lui-liquid-tank: color-mix(in oklab, var(--accent) 70%, #000 30%);
  --lui-liquid-fillc: var(--surface);
  --lui-liquid-icon-lo: #fff;
  --lui-liquid-icon-hi: var(--accent);
  display: inline-grid; justify-items: center; gap: 6px;
}
.lui-liquid[data-tone="dark"] {
  --lui-liquid-main: var(--text); --lui-liquid-main-fg: var(--surface);
  --lui-liquid-tank: color-mix(in oklab, var(--text) 82%, var(--surface) 18%);
  --lui-liquid-fillc: var(--surface);
  --lui-liquid-icon-lo: var(--surface);
  --lui-liquid-icon-hi: var(--text);
}
.lui-liquid[data-tone="light"] {
  --lui-liquid-main: var(--surface); --lui-liquid-main-fg: var(--accent);
  --lui-liquid-tank: var(--surface);
  --lui-liquid-fillc: var(--accent);
  --lui-liquid-icon-lo: var(--accent);
  --lui-liquid-icon-hi: #fff;
}

.lui-liquid-btn {
  display: inline-flex; align-items: stretch; height: var(--lui-liquid-h); padding: 0;
  border: 0; border-radius: var(--r-sm); overflow: hidden;
  background: var(--lui-liquid-main); color: var(--lui-liquid-main-fg);
  font: inherit; font-weight: 650; cursor: pointer; box-shadow: var(--sh-md);
  transition: transform var(--dur-fast), box-shadow var(--dur-fast);
}
.lui-liquid[data-tone="light"] .lui-liquid-btn { border: 1px solid var(--border-strong); }
.lui-liquid-btn:hover:not(:disabled) { transform: translateY(-1px); }
.lui-liquid-btn:focus-visible { outline: none; box-shadow: var(--ring); }
.lui-liquid-btn:disabled { cursor: default; }

.lui-liquid-labelwrap {
  position: relative; display: grid; align-items: center; overflow: hidden;
  min-width: 118px; padding: 0 20px; font-size: var(--fs-sm);
}
.lui-liquid-label { grid-area: 1 / 1; white-space: nowrap; }

.lui-liquid-tank {
  position: relative; display: grid; place-items: center; overflow: hidden;
  width: var(--lui-liquid-h); background: var(--lui-liquid-tank);
}
.lui-liquid-icon {
  position: relative; z-index: 2; display: grid; place-items: center;
  color: var(--lui-liquid-icon-lo); transition: color var(--dur-fast);
}
.lui-liquid[data-high] .lui-liquid-icon { color: var(--lui-liquid-icon-hi); }
.lui-liquid[data-state="error"] .lui-liquid-icon { color: var(--red); }

/* vloeistof: een blok dat van onder omhoog schuift, met een draaiende golf als oppervlak */
.lui-liquid-fill {
  position: absolute; inset: 0; z-index: 1; background: var(--lui-liquid-fillc);
  transform: translateY(100%);
  transition: transform .28s linear;
}
.lui-liquid-wave {
  position: absolute; left: -50%; top: -8px; width: 200%; height: 16px;
  background:
    radial-gradient(circle at 25% 100%, transparent 7px, var(--lui-liquid-fillc) 8px) 0 0 / 22px 16px repeat-x;
  animation: lui-liquid-wave 1.1s linear infinite;
}
.lui-liquid[data-state="idle"] .lui-liquid-wave,
.lui-liquid[data-state="done"] .lui-liquid-wave { opacity: 0; }
@keyframes lui-liquid-wave { to { transform: translateX(22px); } }

.lui-liquid-drop {
  position: absolute; z-index: 1; top: 0; left: 50%; width: 5px; height: 9px; margin-left: -2.5px;
  border-radius: 50% 50% 50% 50% / 60% 60% 40% 40%;
  background: var(--lui-liquid-fillc);
  animation: lui-liquid-drop .45s ease-in forwards;
}
@keyframes lui-liquid-drop { from { transform: translateY(-12px); } to { transform: translateY(calc(var(--lui-liquid-h) - 8px)); } }

.lui-liquid-caption {
  min-height: 1.2em; font-size: 11.5px; color: var(--text-3); font-variant-numeric: tabular-nums;
}

/* ---------- SwipeActions ---------- */
.lui-swipeact {
  position: relative; overflow: hidden; border-radius: var(--r-sm);
  background: var(--surface);
}
.lui-swipeact-front {
  position: relative; z-index: 1; background: var(--surface);
  touch-action: pan-y; user-select: none; cursor: grab;
}
.lui-swipeact-front:active { cursor: grabbing; }

.lui-swipeact-side {
  --lui-sa-tone: var(--red);
  position: absolute; top: 0; bottom: 0; display: flex; overflow: hidden;
  background: var(--lui-sa-tone);
}
.lui-swipeact-side[data-side="leading"] { left: 0; }
.lui-swipeact-side[data-side="trailing"] { right: 0; justify-content: flex-end; }
.lui-swipeact-side[data-tone="teal"], .lui-swipeact-btn[data-tone="teal"] { --lui-sa-tone: color-mix(in oklab, var(--green) 55%, var(--blue)); }
.lui-swipeact-side[data-tone="accent"], .lui-swipeact-btn[data-tone="accent"] { --lui-sa-tone: var(--accent); }
.lui-swipeact-side[data-tone="amber"], .lui-swipeact-btn[data-tone="amber"] { --lui-sa-tone: var(--amber); }
.lui-swipeact-side[data-tone="blue"], .lui-swipeact-btn[data-tone="blue"] { --lui-sa-tone: var(--blue); }
.lui-swipeact-side[data-tone="neutral"], .lui-swipeact-btn[data-tone="neutral"] { --lui-sa-tone: color-mix(in oklab, var(--text-3) 80%, var(--surface)); }
.lui-swipeact-btn[data-tone="red"] { --lui-sa-tone: var(--red); }

.lui-swipeact-btn {
  display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 3px;
  flex: 1 1 0; min-width: 0; padding: 0 6px; border: 0;
  background: var(--lui-sa-tone); color: #fff; cursor: pointer;
  font: inherit; font-size: 11px; font-weight: 650;
  transition: flex-grow .28s var(--ease-pop), opacity var(--dur);
}
.lui-swipeact-btn:focus-visible { outline: 2px solid #fff; outline-offset: -4px; }
.lui-swipeact-label { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 100%; }
.lui-swipeact-btn svg { transition: transform .25s var(--ease-pop); }

/* Voorbij de commit-lijn neemt de hoofdactie de hele breedte in, met een "tik". */
.lui-swipeact-side[data-armed] .lui-swipeact-btn[data-primary] { flex-grow: 60; }
.lui-swipeact-side[data-armed] .lui-swipeact-btn:not([data-primary]) { flex-grow: .0001; opacity: 0; }
.lui-swipeact-side[data-armed] .lui-swipeact-btn[data-primary] svg { transform: scale(1.25); animation: lui-swipeact-tick .28s var(--ease-pop); }
.lui-swipeact-side[data-side="trailing"][data-armed] .lui-swipeact-btn[data-primary] { justify-content: center; align-items: flex-start; padding-inline-start: 22px; }
.lui-swipeact-side[data-side="leading"][data-armed] .lui-swipeact-btn[data-primary] { align-items: flex-end; padding-inline-end: 22px; }
@keyframes lui-swipeact-tick { 0% { transform: scale(1); } 50% { transform: scale(1.45); } 100% { transform: scale(1.25); } }
